"""T01 same-authority migration fragment; T00/I00 alone may execute it."""

from __future__ import annotations


FORMAL_BRIEF_MIGRATION_NAME = "t01_formal_brief_v2"
FORMAL_BRIEF_TABLES = ("project_files", "document_extractions", "document_locations", "document_images", "brief_versions", "brief_facts", "brief_conflicts", "brief_confirmations")


def authoritative_migration_fragment() -> tuple[str, ...]:
    """DDL requiring the existing WorkspaceStore/PostgreSQL transaction and FKs."""
    tables = (
        """CREATE TABLE project_files(file_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(workspace_id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, source_document_id TEXT NOT NULL, relative_path TEXT NOT NULL, filename TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes BIGINT NOT NULL CHECK(size_bytes >= 0), sha256 TEXT NOT NULL, artifact_ref TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('frozen','extracted','failed')), critical BOOLEAN NOT NULL, created_by_actor_id TEXT NOT NULL REFERENCES actors(actor_id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(project_id, source_document_id), UNIQUE(project_id, sha256))""",
        """CREATE TABLE document_extractions(extraction_id TEXT PRIMARY KEY, file_id TEXT NOT NULL UNIQUE REFERENCES project_files(file_id) ON DELETE RESTRICT, status TEXT NOT NULL CHECK(status IN ('succeeded','failed')), critical BOOLEAN NOT NULL, error_code TEXT, error_message TEXT, created_at TEXT NOT NULL)""",
        """CREATE TABLE document_locations(location_id TEXT PRIMARY KEY, extraction_id TEXT NOT NULL REFERENCES document_extractions(extraction_id) ON DELETE RESTRICT, source_document_id TEXT NOT NULL, artifact_ref TEXT NOT NULL, content_sha256 TEXT NOT NULL, location_json TEXT NOT NULL, text_content TEXT NOT NULL, UNIQUE(extraction_id, artifact_ref))""",
        """CREATE TABLE document_images(document_image_id TEXT PRIMARY KEY, file_id TEXT NOT NULL REFERENCES project_files(file_id) ON DELETE RESTRICT, source_document_id TEXT NOT NULL, image_sha256 TEXT NOT NULL, artifact_ref TEXT NOT NULL, content_sha256 TEXT NOT NULL, location_json TEXT NOT NULL, UNIQUE(file_id, image_sha256, artifact_ref))""",
        """CREATE TABLE brief_versions(brief_version_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(workspace_id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, parent_brief_version_id TEXT REFERENCES brief_versions(brief_version_id) ON DELETE RESTRICT, source_manifest_ref TEXT NOT NULL, source_manifest_sha256 TEXT NOT NULL, source_document_ids_json TEXT NOT NULL, payload_ref TEXT NOT NULL, payload_sha256 TEXT NOT NULL, created_by_actor_id TEXT NOT NULL REFERENCES actors(actor_id) ON DELETE RESTRICT, created_at TEXT NOT NULL, UNIQUE(project_id, payload_sha256))""",
        """CREATE TABLE brief_facts(fact_id TEXT PRIMARY KEY, brief_version_id TEXT NOT NULL REFERENCES brief_versions(brief_version_id) ON DELETE RESTRICT, field_path TEXT NOT NULL, value_json TEXT NOT NULL, certainty TEXT NOT NULL CHECK(certainty IN ('confirmed','pending')), confidence TEXT NOT NULL CHECK(confidence IN ('high','medium','low')), evidence_refs_json TEXT NOT NULL)""",
        """CREATE TABLE brief_conflicts(conflict_id TEXT PRIMARY KEY, brief_version_id TEXT NOT NULL REFERENCES brief_versions(brief_version_id) ON DELETE RESTRICT, field_path TEXT NOT NULL, fact_ids_json TEXT NOT NULL, evidence_refs_json TEXT NOT NULL, resolution_status TEXT NOT NULL CHECK(resolution_status IN ('unresolved','resolved')), resolved_fact_id TEXT REFERENCES brief_facts(fact_id) ON DELETE RESTRICT, resolved_by_actor_id TEXT REFERENCES actors(actor_id) ON DELETE RESTRICT, resolved_at TEXT, resolution_evidence_ref TEXT, resolution_evidence_sha256 TEXT, CHECK((resolution_status = 'unresolved' AND resolved_fact_id IS NULL AND resolved_by_actor_id IS NULL AND resolved_at IS NULL AND resolution_evidence_ref IS NULL AND resolution_evidence_sha256 IS NULL) OR (resolution_status = 'resolved' AND resolved_fact_id IS NOT NULL AND resolved_by_actor_id IS NOT NULL AND resolved_at IS NOT NULL AND resolution_evidence_ref IS NOT NULL AND resolution_evidence_sha256 IS NOT NULL)))""",
        """CREATE TABLE brief_confirmations(confirmation_id TEXT PRIMARY KEY, brief_version_id TEXT NOT NULL UNIQUE REFERENCES brief_versions(brief_version_id) ON DELETE RESTRICT, brief_snapshot_id TEXT NOT NULL UNIQUE REFERENCES project_brief_snapshots(brief_snapshot_id) ON DELETE RESTRICT, workspace_id TEXT NOT NULL REFERENCES workspaces(workspace_id) ON DELETE RESTRICT, project_id TEXT NOT NULL REFERENCES projects(project_id) ON DELETE RESTRICT, confirmation_status TEXT NOT NULL CHECK(confirmation_status IN ('confirmed')), unresolved_conflict_count INTEGER NOT NULL CHECK(unresolved_conflict_count >= 0), confirmed_by_actor_id TEXT NOT NULL REFERENCES actors(actor_id) ON DELETE RESTRICT, confirmed_at TEXT NOT NULL)""",
    )
    indexes = tuple(f"CREATE INDEX {table}_workspace_project_idx ON {table}(workspace_id, project_id)" for table in ("project_files", "brief_versions", "brief_confirmations")) + ("CREATE INDEX document_extractions_file_idx ON document_extractions(file_id)", "CREATE INDEX document_locations_extraction_idx ON document_locations(extraction_id)", "CREATE INDEX document_images_file_idx ON document_images(file_id)", "CREATE INDEX brief_facts_version_idx ON brief_facts(brief_version_id)", "CREATE INDEX brief_conflicts_version_idx ON brief_conflicts(brief_version_id)")
    triggers = tuple(f"CREATE TRIGGER {table}_{action}_immutable BEFORE {action.upper()} ON {table} BEGIN SELECT RAISE(ABORT, 'IMMUTABLE_RECORD'); END" for table in FORMAL_BRIEF_TABLES for action in ("update", "delete"))
    relationship_checks = (
        """CREATE TRIGGER project_files_workspace_project_match BEFORE INSERT ON project_files BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM projects WHERE project_id=NEW.project_id AND workspace_id=NEW.workspace_id) THEN RAISE(ABORT, 'PROJECT_WORKSPACE_MISMATCH') END; END""",
        """CREATE TRIGGER brief_versions_workspace_project_match BEFORE INSERT ON brief_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM projects WHERE project_id=NEW.project_id AND workspace_id=NEW.workspace_id) THEN RAISE(ABORT, 'PROJECT_WORKSPACE_MISMATCH') END; END""",
        """CREATE TRIGGER document_extractions_frozen_critical BEFORE INSERT ON document_extractions BEGIN SELECT CASE WHEN NEW.critical != (SELECT critical FROM project_files WHERE file_id=NEW.file_id) THEN RAISE(ABORT, 'FROZEN_CRITICAL_MISMATCH') END; END""",
        """CREATE TRIGGER document_locations_source_match BEFORE INSERT ON document_locations BEGIN SELECT CASE WHEN NEW.source_document_id != (SELECT source_document_id FROM project_files WHERE file_id=(SELECT file_id FROM document_extractions WHERE extraction_id=NEW.extraction_id)) THEN RAISE(ABORT, 'DOCUMENT_SOURCE_MISMATCH') END; END""",
        """CREATE TRIGGER document_images_source_match BEFORE INSERT ON document_images BEGIN SELECT CASE WHEN NEW.source_document_id != (SELECT source_document_id FROM project_files WHERE file_id=NEW.file_id) THEN RAISE(ABORT, 'DOCUMENT_SOURCE_MISMATCH') END; END""",
        """CREATE TRIGGER brief_confirmations_binding_match BEFORE INSERT ON brief_confirmations BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM brief_versions WHERE brief_version_id=NEW.brief_version_id AND project_id=NEW.project_id AND workspace_id=NEW.workspace_id) OR NOT EXISTS(SELECT 1 FROM project_brief_snapshots WHERE brief_snapshot_id=NEW.brief_snapshot_id AND project_id=NEW.project_id) THEN RAISE(ABORT, 'CONFIRMATION_BINDING_MISMATCH') END; END""",
    )
    return tables + indexes + triggers + relationship_checks
